  target_bucket = aws_s3_bucket.firehose_logs.id
  target_prefix = "logs/"
}

resource "aws_iam_role_policy" "firehose_s3" {
  name = "firehose-s3-policy"
  role = aws_iam_role.firehose.id

  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [{
      Effect = "Allow",
      Action = [
        "s3:AbortMultipartUpload",
        "s3:GetBucketLocation",
        "s3:GetObject",
        "s3:ListBucket",
        "s3:ListBucketMultipartUploads",
        "s3:PutObject"
      ],
      Resource = [
        aws_s3_bucket.firehose_logs.arn,
        "${aws_s3_bucket.firehose_logs.arn}/*"
      ]
    }]
  })
}

resource "aws_kinesis_firehose_delivery_stream" "main" {
  name        = "my-firehose-delivery-stream"
  destination = "extended_s3"

  extended_s3_configuration {
    role_arn           = aws_iam_role.firehose.arn
    bucket_arn         = aws_s3_bucket.firehose_logs.arn
    prefix             = "firehose-data/"
    error_output_prefix = "errors/"
    buffering_interval = 300
    buffering_size     = 5
    compression_format = "GZIP"
    data_format_conversion_configuration {
      input_format   = "JSON"
      output_format  = "JSON"
      enabled        = true
      schema_configuration {
        database_name       = "my_database"
        table_name          = "my_table"
        role_arn            = aws_iam_role.firehose.arn
        region              = "us-east-1"
        version_id          = "LATEST"
      }
    }
    dynamic_partitioning_configuration {
      enabled = true
    }
    kms_key_arn = aws_kms_key.main.arn
    cloudwatch_logging_options {
      enabled         = true
      log_group_name  = aws_cloudwatch_log_group.firehose.name
      log_stream_name = "firehose-stream"
    }
  }
}

